event.script:
var reg = new RegExp("^([\\w]|[\\s]|[-]|[.])+$");
if(!reg.test(xfa.event.change))
{
xfa.event.change = "";
}

if(this.access == "open") {
   try{
   if(this.rawValue != null){
	   this.rawValue = this.rawValue.replace(/^\s+|\s+$/gm,'');	
	   var validCNP = cnp.validcnp(this.rawValue);	
	   if(validCNP  == false){
		   xfa.host.messageBox("Codul de indetificare fiscala nu este valid","DOCUMENT DE FUNDAMENTARE");
		   xfa.host.setFocus(this);}
	   }	
}catch(e){
  xfa.host.messageBox(e.name+""+e.message);
}
}

if(this.access == "open") {
   try {
      if(this.rawValue != null){ 
         if(this.rawValue.length !=10 ){xfa.host.setFocus(this); xfa.host.messageBox("Lungime data incorecta " + this.rawValue.length +  " !!!");}
         var van=""; 
         var vluna="";
         var vzi="";
         if(!(this.rawValue.indexOf("-") == -1)) { // am completat cu calendarul si data.rawValue e de forma yyyy-mm-dd   
           van = this.rawValue.substring(0,4) ;
           vluna = this.rawValue.substring(5,7) ;
           vzi = this.rawValue.substring(8) ; 
         }else { if(!(this.rawValue.indexOf(".") == -1)) { // am completat de mana cu . data e de forma zz.mm.yyyy 
                                                          van = this.rawValue.substring(6,10) ;
                                                          vluna  = this.rawValue.substring(3,5) ;
                                                          vzi = this.rawValue.substring(0,2) ;
                                                         } else {xfa.host.setFocus(this); xfa.host.messageBox("Data incorecta!!!"); }      
               }
                //xfa.host.messageBox(vzi + "." + vluna + "." + van );
		        var regd = new RegExp("^([0-9]*)$");
                var rvan = regd.test(van);
                var rvluna = regd.test(vluna);
                var rvzi = regd.test(vzi);

                //if(!reg.test(xfa.event.newText))

		        if (vluna > 12 || vzi > 31 || van < 2020 || van > 2100 || !rvan || !rvluna || !rvzi ) {xfa.host.setFocus(this); xfa.host.messageBox("Data incorecta!!! " + " vzi" +  vzi + "." + vluna + "." + van );}  
	   }   
   }catch(e){
     xfa.host.messageBox(e.name+""+e.message);
     console.show();  }
}

try {

