   }
//verific structura Cod SSI, sector 2 car numerice 01->05, sursa 1 car nenumeric, indicator 12 car numerice
var sec_SSI = this.rawValue.substring(0,2);
var suc_SSI = this.rawValue.substring(2,3);
var iic_SSI = this.rawValue.substring(3);
//xfa.host.messageBox(sec_SSI + "  " + suc_SSI + "  " + iic_SSI ); 					  
var TheErrMsgBT = "";
if( !(sec_SSI == "01" ||sec_SSI == "02" ||sec_SSI == "03" ||sec_SSI == "04" ||sec_SSI == "05")  ) {
     TheErrMsgBT += "Primele doua caractere din Cod SSI (cod sector) trebuie sa fie in intervalul 01-05  " + "\r\n";
}
if( !isNaN(suc_SSI) ) {
     TheErrMsgBT += "Al treilea caracter din Cod SSI (cod sursa) , trebuie sa fie nenumeric " + "\r\n";
}					  

if(!csGlobals.Data().validSursa(suc_SSI)) {TheErrMsgBT += "Al treilea caracter din Cod SSI (cod sursa) , nu se gaseste in nomenclator " + "\r\n";}

var regiiC = new RegExp("^([0-9]*)$");
var rviiC = regiiC.test(iic_SSI);
if(!rviiC){
     TheErrMsgBT += "Ultimele 12 caractere din Cod SSI (cod COFOG3) , trebuie sa fie numerice " + "\r\n";
}                      					  

if(!(Cell3.rawValue.toUpperCase()=="0000000000")){
   gasitProgramSector = csGlobals.Data().validProgramSector(Cell3.rawValue.toUpperCase(), sec_SSI);
   if(!gasitProgramSector) {TheErrMsgBT += "Campul Program " + Cell3.rawValue.toUpperCase()+   " nu exista in nomenclator pentru acest sector bugetar " + sec_SSI  + "\r\n";}
}       

if(TheErrMsgBT !="") { xfa.host.messageBox(TheErrMsgBT); xfa.host.setFocus(this); }

}


