//xfa.host.messageBox("5 AButtonCnt " + AButtonCnt );   
for(i=0; i<AButtonCnt; i++ ) {
    //xfa.host.messageBox("i " + i );
	var TheRowInf =  FData.SubformInf.all.item(i);
    //xfa.host.messageBox("i " + i  + "  " +  TheRowInf.Subform1.NrUnicInreg.rawValue );
    //xfa.host.messageBox("i " + i  + " Table1._Row1.count " +  TheRowInf.Table1._Row1.count);

	 var cntTable1 = TheRowInf.Table1._Row1.count;
     if(cntTable1==1) {TheErrMsg += "Nu aveti randuri introduse in tabel " + "\r\n"; }
	 if(stsmn=="1") {
	 for(j=1; j<cntTable1; j++ ) {
         //xfa.host.messageBox("i j" + i  + " " + j );
		 var TheRowT1 = TheRowInf.Table1.Row1.all.item(j) ;
         //xfa.host.messageBox("i j" + i  + " " + j +  " Cell1.rawValue " +  TheRowT1.Cell1.rawValue );
         // Cell1 , Cod angajament
        if(TheRowT1.Cell7.access == "readOnly" ) { // Coloana 4 inghetata, tb ca linia tabelului sa fie completata, altfel nu
           completatC1234 = true;
		   if(TheRowT1.Cell1.rawValue == null || TheRowT1.Cell1.rawValue == "" ) {
               TheErrMsg += "Nu ati completat coloana ,Cod angajament,  randul " + j + "\r\n"; completatC1234 = false;}
           if(TheRowT1.Cell2.rawValue == null || TheRowT1.Cell2.rawValue == "" ) {
               TheErrMsg += "Nu ati completat coloana ,Indicator angajament,  randul " + j + "\r\n"; completatC1234 = false;}
           if(TheRowT1.Cell3.rawValue == null || TheRowT1.Cell3.rawValue == "" ) {
               TheErrMsg += "Nu ati completat coloana ,Cod program,  randul " + j + "\r\n"; completatC1234 = false;}
		   if(TheRowT1.Cell4.rawValue == null || TheRowT1.Cell4.rawValue == "" ) {
              TheErrMsg += "Nu ati completat coloana ,Cod SSI,  randul " + j + "\r\n"; completatC1234 = false;}

		   if(completatC1234) {	   
		       if(TheRowT1.Cell1.rawValue.length != 11) {TheErrMsg += "Cod angajament nu are lungimea de 11 caractere !!!" + TheRowT1.Cell1.rawValue + "\r\n";}
		       if(TheRowT1.Cell2.rawValue.length != 3)  {TheErrMsg += "Indicator angajament nu are lungimea de 3 caractere !!! " + TheRowT1.Cell2.rawValue + "\r\n";}
		       if(TheRowT1.Cell3.rawValue.length != 10) {TheErrMsg += "Cod program nu are lungimea de 10 caractere !!! " + TheRowT1.Cell3.rawValue + "\r\n";}
		       if(TheRowT1.Cell4.rawValue.length != 15) {TheErrMsg += "Cod SSI nu are lungimea de 15 caractere !!! " + TheRowT1.Cell4.rawValue + "\r\n";}
           }
        } 

         if(TheRowT1.Cell4.rawValue == null || TheRowT1.Cell4.rawValue == "" ) {
               TheErrMsg += "Nu ati completat coloana ,Cod SSI,  randul " + j + "\r\n";}
         else {if(TheRowT1.Cell4.rawValue.length !=15 ) {TheErrMsg += "Coloana ,Cod SSI, randul " + j + " nu are 15 caractere "  + TheRowT1.Cell4.rawValue.length + " " +   "\r\n"; }
               else{ //verific structura Cod SSI, sector 2 car numerice 01->05, sursa 1 car nenumeric, indicator 12 car numerice
                      var se_SSI = TheRowT1.Cell4.rawValue.substring(0,2);
