                          //xfa.host.messageBox("13"); 

                      }       


					  var regii = new RegExp("^([0-9]*)$");
                      var rvii = regii.test(ii_SSI);
                      if(!rvii){TheErrMsg += "Ultimele 12 caractere din Cod SSI (cod COFOG3) , randul " + j + "trebuie sa fie numerice " + "\r\n";}                      					  
	                }
               } 
           // verific sa am cel putin o suma completata
           if((TheRowT1.Cell5.rawValue == null || TheRowT1.Cell5.rawValue == 0) &&  
		      (TheRowT1.Cell6.rawValue == null || TheRowT1.Cell6.rawValue == 0) &&
              (TheRowT1.Cell7.rawValue == null || TheRowT1.Cell7.rawValue == 0) &&  			  
			  (TheRowT1.Cell8.rawValue == null || TheRowT1.Cell8.rawValue == 0)) {
			   TheErrMsg += "Nu ati completat nici o valoare in coloanele 2, 3 , 4, 5 , randul " + j + "" + "\r\n"; 
			  } else {  if(TheRowT1.Cell5.rawValue < 0) {TheErrMsg += "Nu se accepta valori negative in coloana 2 Receptii " + TheRowT1.Cell5.rawValue + " , randul " +  "  " +  j + "" + "\r\n"; }
                        if(TheRowT1.Cell6.rawValue < 0) {TheErrMsg += "Nu se accepta valori negative in coloana 3 Plati anterioare " + TheRowT1.Cell6.rawValue + " , randul " +  "  " +  j + "" + "\r\n"; }
                        if(TheRowT1.Cell7.rawValue < 0) {if(Math.abs(TheRowT1.Cell7.rawValue) > Math.abs(TheRowT1.Cell6.rawValue)) { TheErrMsg += "Coloana 4 Suma ordonantata la plata nu poate fi mai mare ca si  coloana 3 Plati anterioare!!! " +  Math.abs(TheRowT1.Cell7.rawValue) + " > " +  Math.abs(TheRowT1.Cell6.rawValue ) + " , randul " +  "  " +  j + "" + "\r\n";  }}
                        if(TheRowT1.Cell8.rawValue < 0) {TheErrMsg += "Nu se accepta valori negative in coloana 5 Receptii neplatite " + TheRowT1.Cell8.rawValue + " , randul " +  "  " +  j + "" + "\r\n"; }
			         }
	   }// endfor Tabel
        var cntTable2 = TheRowInf.SubformCaptura.Table2._Row1.count;
        //if(cntTable2==1) {TheErrMsg += "Nu aveti introdusa o captura de imagine " + "\r\n"; }

	  }


       if(TheRowInf.SubformBeneficiar.SubformBen.Beneficiar.rawValue == null || TheRowInf.SubformBeneficiar.SubformBen.Beneficiar.rawValue == "" ) {
		   TheErrMsg += "Nu ati completat campul Beneficiar " + "\r\n"; 
	   }

	   if(TheRowInf.SubformBeneficiar.SubformBen.DocumenteJustificative.rawValue == null || TheRowInf.SubformBeneficiar.SubformBen.DocumenteJustificative.rawValue == "" ) {
		   TheErrMsg += "Nu ati completat campul DocumenteJustificative " + "\r\n"; 
	   }

       if(TheRowInf.SubformBeneficiar.SubformBen1.CifBeneficiar.rawValue == null || TheRowInf.SubformBeneficiar.SubformBen1.CifBeneficiar.rawValue == "" ) {
		   //if(stsmn=="1") { TheErrMsg += "Nu ati completat campul CifBeneficiar " + "\r\n"; }
	   } else {	var validCNP = cnp.validcnp(TheRowInf.SubformBeneficiar.SubformBen1.CifBeneficiar.rawValue);	
	            if(validCNP  == false){
		            TheErrMsg += "Codul de indetificare fiscala beneficiar nu este valid " + TheRowInf.SubformBeneficiar.SubformBen1.CifBeneficiar.rawValue + "\r\n"; 
	                                  }
	          }

       if(TheRowInf.SubformBeneficiar.SubformBen1.IbanBeneficiar.rawValue == null || TheRowInf.SubformBeneficiar.SubformBen1.IbanBeneficiar.rawValue == "" ) {
		   //if(stsmn=="1") {TheErrMsg += "Nu ati completat campul IbanBeneficiar " + "\r\n"; }
	   } else{if(TheRowInf.SubformBeneficiar.SubformBen1.IbanBeneficiar.rawValue.substr(0,2) == "RO") {
			      var TheResult = csGlobals.Data().validIBAN(TheRowInf.SubformBeneficiar.SubformBen1.IbanBeneficiar.rawValue);
                  if(TheResult.ver_iban == true) {
                     //xfa.host.messageBox("IBAN corect"); RO07TREZ0618101A980400XX  RO08TREZ24A675000203030X RO44BACX0000000503959048 RO47BTRL00501202742595XX
                     var TheResultBC = csGlobals.Data().cautBICBanca(TheRowInf.SubformBeneficiar.SubformBen1.IbanBeneficiar.rawValue);
			         //xfa.host.messageBox("iban_pl::exit codbanca " + TheResultBC.codbanca);
			         //xfa.host.messageBox("iban_pl::exit denumiredbanca " + TheResultBC.denbanca);
                    if(!(TheRowInf.SubformBeneficiar.SubformBen1.IbanBeneficiar.rawValue.substr(4,4) == "TREZ")) {//TheErrMsgInf += "Iban corect! " + "\r\n" + "Nu este un IBAN de trezorerie !!!";
                                                                                                                }

                  }else { TheErrMsg += "Cod iban beneficiar incorect " + "\r\n"; }
               }else {TheErrMsgInf += "Nu este IBAN romanesc, nu exista un algoritm de verificare!!! "  + "\r\n";}
            }
       if(TheRowInf.SubformBeneficiar.SubformBen1.BancaBeneficiar.rawValue == null || TheRowInf.SubformBeneficiar.SubformBen1.BancaBeneficiar.rawValue == "" ) {
		   //if(stsmn=="1") {TheErrMsg += "Nu ati completat campul BancaBeneficiar " + "\r\n"; }
	   }

       if(TheRowInf.SubformBeneficiar.SubformBen1.InfPvPlata.rawValue == null || TheRowInf.SubformBeneficiar.SubformBen1.InfPvPlata.rawValue == "" ) {
		   TheErrMsg += "Nu ati completat campul Informatii Privind Plata " + "\r\n"; 
	   }



} // endfor 2, cel cu multiplicare forma

//if(FData.CheckBox1.rawValue == 0 && FData.CheckBox2.rawValue == 0 ) {TheErrMsg += "Nu ati selectat o optiune din cele doua: avizam favorabil sau refuzam viza " + "\r\n";  }   
//if(FData.CheckBox3.rawValue == 0 && FData.CheckBox4.rawValue == 0  && FData.CheckBox5.rawValue == 0) {TheErrMsg += "Nu ati selectat o optiune din cele trei: avizam favorabil sau exprimam intentia de refuz de viza sau refuzam viza " + "\r\n";  }   

    // afisez mesaj de atentionare
   if(TheErrMsgInf != "" ) { 
      xfa.host.messageBox(TheErrMsgInf);
   } 

   if(TheErrMsg != "" ) { 
      xfa.host.messageBox(TheErrMsg);
   } else {
     xfa.host.messageBox("Nu sunt erori ");
   }

return TheErrMsg;

}

FData.validSursa = function(ASursa){
    var gasitSursa = false;
    for(i=0;i<FData.NomenValue_Sursa.length;i++){
        if(ASursa == FData.NomenValue_Sursa[i][0]) {gasitSursa = true; break; } 
    }

    return gasitSursa;
}


FData.validProgram = function(AProgram){
    var gasitProgram = false;
    for(i=0;i<FData.NomenValue_PrgBug.length;i++){
        if(AProgram == FData.NomenValue_PrgBug[i][0]) {gasitProgram = true; break; } 
    }

    return gasitProgram;
}

FData.validProgramSector = function(AProgram, ASector){
    var gasitProgram = false;
    for(i=0;i<FData.NomenValue_PrgBug.length;i++){
        if((AProgram == FData.NomenValue_PrgBug[i][0]) && (ASector == FData.NomenValue_PrgBug[i][3])) {gasitProgram = true; break; } 
    }
    return gasitProgram;
}



FData.validData = function(AData){
      var TheErrData ="";
       var van=""; 
       var vluna="";
       var vzi="";

	  if(AData.rawValue != null){ 
         if(AData.rawValue.length !=10 ){ TheErrData += "Lungime data incorecta camp data " + AData.rawValue.length + "\r\n"; return TheErrData; }
           if(!(AData.rawValue.indexOf("-") == -1)) { // am completat cu calendarul si data.rawValue e de forma yyyy-mm-dd   
           van = AData.rawValue.substring(0,4) ;
           vluna = AData.rawValue.substring(5,7) ;
           vzi = AData.rawValue.substring(8) ; 
         }else { if(!(AData.rawValue.indexOf(".") == -1)) { // am completat de mana cu . data e de forma zz.mm.yyyy 
                                                          van = AData.rawValue.substring(6,10) ;
                                                          vluna  = AData.rawValue.substring(3,5) ;
                                                          vzi = AData.rawValue.substring(0,2) ;
                                                         } else {TheErrData += "Data incorecta!!! "  + "\r\n"; 
                                                                 return TheErrData;
           														 }      
               }

		        var regd = new RegExp("^([0-9]*)$");
                var rvan = regd.test(van);
                var rvluna = regd.test(vluna);
                var rvzi = regd.test(vzi);



		        if ( vluna > 12 || vzi > 31 || van < 2020 || van >= 2100 || !rvan || !rvluna || !rvzi ) {TheErrData += "Data incorecta!!! " + " vzi" +  vzi + "." + vluna + "." + van + "\r\n";}  
	   }   
  return TheErrData;
} 


FData.validIBAN = function(iban){
    var TheResult = new Object();
    var c3 = "";
    var c3 = ""; //sirul convertit
    var X="";
    var cbug = iban;
    var lliban = cbug.length;
    TheResult.ver_iban = false;
    //console.println("cbug  lliban " + cbug + " " + lliban );
    if(lliban<24) {
    	if(lliban>0) {
    	   for(i=1; i<= 24-lliban; i++) {
    	      cbug = cbug + "X"; }
    	} else { return TheResult;}
        //FData.Iban_bn = cbug;
    } 
    if(cbug.substr(0,2) !="RO"){ return TheResult; } 
    X = cbug.substr(4) + "RO00";
    //xfa.host.messageBox("validIBAN  X " + X);
    var llX = X.length;
    //console.println("X  llX " + X + " " + llX); 
    for(i=1; i<=llX; i++) {
    	c2 = X.substr(i-1,1);
    	//console.println(" i  c2 codASCII "  + i + " " + c2 + "  " + c2.charCodeAt(0));
    	if( (c2.charCodeAt(0)>47 && c2.charCodeAt(0)<58)  || (c2.charCodeAt(0)>64 && c2.charCodeAt(0)<91) ) {
    	   if(c2.charCodeAt(0)>47 && c2.charCodeAt(0)<58) {
    	      c3 = c3 + c2;
    	      //console.println(" i  c3 "  + i + " " + c3);
    	       }

    	   else {
    	      c3 = c3 +  (c2.charCodeAt(0) - 55) ; }   
              //console.println(" ielse  c3 "  + i + " " + c3);

    	}
    }
    //xfa.host.messageBox("c3 apelare mod97  "  + c3);
    //console.println("c3 apelare mod97  "  + c3);
    //console.show();
    var rest = FData.Mod97(c3); 
    TheResult.cifra_corecta = rest;
    //console.println(" rest  cbug.substr(2,2)  parseInt(cbug.substr(2,2)) "  + rest + " "  + cbug.substr(2,2) + " " + parseInt(cbug.substr(2,2)));

    if( rest != cbug.substr(2,2) ) { TheResult.ver_iban = false;   } else {TheResult.ver_iban = true; }
    //console.show();
    return TheResult; 
}


FData.Mod97 = function(sir){
    //console.println('mod97');
    var nr = 0;
    var nl = 0;
    var ll = 0;
    var ll9 = 0;
    var mod97 = "";
    var n9 = 0;
    var cn9 = "";
    var rest = 0;
    for(kk=1; kk<9; kk++) {
       //console.println("kk " + kk);
       if(sir.length <10 ) {
            //console.println("sir.length <10");
            //console.println("sir " + sir);
            cn9 = FData.sterg_zero_prim(sir);
            n9 = parseInt(cn9);

            rest = n9 % 97;
            //console.println("n9 " + n9 + " rest " + rest);
            break;
         }
       else {
           //console.show();
           //console.println("sir.length>9  sir " + sir);
           cn9 = FData.sterg_zero_prim(sir.substr(0,9));
           n9 =  parseInt(cn9);

           rest = n9 % 97;
           //xfa.host.messageBox(" n9 " + n9  + " rest " + rest); 
           //console.println(" n9 " + n9  + " rest " + rest);
           ll = sir.length;
           ll9 = 9;
           //console.println(" sir.length  + ll9 " + ll + " " + ll9 );
          // xfa.host.messageBox(" sir right length " + ll + " " + ll9 );
            //console.println(" sir.substr(ll9) " + sir.substr(ll9));
          // xfa.host.messageBox(" sir right " + sir.substr(ll9));
           sir = rest + sir.substr(ll9);   //, Len(sir) - 9); 
           //console.println(" sir final =  rest + sir.substr(ll9)  " + sir);
           //xfa.host.messageBox(" sir final  " + sir);
       }
    }
    nr = 98 - rest;
    //console.println(" nr " + nr + " rest " + rest + "  nrlength " + nr.toString().length);    
    //xfa.host.messageBox(" nr " + nr + " rest " + rest + "  nrlength " + nr.toString().length);    
    nl = nr.toString().length ;

    if(nl == 2) { mod97 = nr;}
    else (mod97 = "0" + nr)
    //mod97 = IIf(Len(n) = 2, n, "0" & n);
    //console.println(" mod97 " + mod97 + " nl " + nl);    
    //xfa.host.messageBox(" mod97 " + mod97 + " nl " + nl); 
    //console.show();
    return mod97;
} 

