       if(isNaN(z1u)) {z1 = iban.substr(4,4); // z1 este TREZ de fapt, cind am cod sursa in pozitia 11  
	                         }  // caract este sursa finantare, z1u         
    }else {z1 = iban.substr(4,4);}

    //TheTrzCnt = FData.NomenTrezorerii.Values.length;
    //xfa.host.messageBox("NomenBanci1 length  " + llitemb );
    var TheItemB = "";
    var TheLineBanca = "";
