        var TheLineBanca = TheItems[TheItem];
        TheItemB =  TheLineBanca[0] + " " + TheLineBanca[1];
        if(z1.length==7) {z2 = TheLineBanca[0].substr(0,7); } // trezorerii
        if(z1.length==4) {z2 = TheLineBanca[0].substr(0,4); } // banci
        if(z1==z2){
            //xfa.host.messageBox("cautBICBanca 4 z1  z2 " + z1 + " " + z2);
            TheResult.codbanca = TheLineBanca[0];
            TheResult.denbanca = TheLineBanca[1];
            break; // ies din bucla odata ce am gasit banca
        } // z1==z2
     }


   return TheResult ;
}



