FDataTool = null;

function GetInstance(){
  if(FDataTool){
    return FDataTool;
  }
  var TheMethods = DataToolMethods();
  FDataTool = new Object();
  // consts & variables
  FDataTool.Data = csGlobals.Data();
  FDataTool.Declaratie = FDataTool.Data.Declaratie;
  FDataTool.Form = event.target;
  FDataTool.Xml = '';

  // methods
  //FDataTool.GetControlSum = TheMethods.GetControlSum;
  FDataTool.ExecuteExport = TheMethods.ExecuteExport;
  FDataTool.ExecuteImport = TheMethods.ExecuteImport;
  FDataTool.LoadFormDataFromXml = TheMethods.LoadFormDataFromXml;
  FDataTool.LoadXmlFromFile = TheMethods.LoadXmlFromFile;
  //FDataTool.ValidateCui = TheMethods.ValidateCui;
  //FDataTool.ValidateFormData = TheMethods.ValidateFormData;
  //FDataTool.AntetCmpl = TheMethods.AntetCmpl;

  // private data + methods
  FDataTool.__GenerateXml = TheMethods.__GenerateXml;
  FDataTool.__RemoveAttachedFiles = TheMethods.__RemoveAttachedFiles;
  FDataTool.__ValidationMessages = '';
  //FDataTool.__MsgErrImpXml = '';
  return FDataTool;
}


function DataToolMethods(){
  var TheMethods = new Object();


  TheMethods.__RemoveAttachedFiles = function(){
    var TheDataObjects = this.Form.dataObjects;
    if (TheDataObjects == null){
      return;
    }
    for (var I = 0; I < TheDataObjects.length; I++){
      this.Form.removeDataObject(TheDataObjects[I].name);
    }
  };

  TheMethods.ExecuteImport = function(){
    this.__DoExecuteImport = this.__DoExecuteImport?this.__DoExecuteImport:function(){
      this.LoadXmlFromFile();
      //this.Xml= "<?xml version='1.0'?><f1129 xmlns:xsi='http://www.w3.org/2001/XMLSchema-instance' xsi:schemaLocation='mfp:anaf:dgti:f1129:declaratie:v1' xmlns='mfp:anaf:dgti:f1129:declaratie:v1' d_rec='0' suma_control='5354' luna_r='09' an='2017' data_document='14.09.2017' nume_ip='den platoy uuuuu' adresa_ip='adresa pl jjjjjjj' cui_ip='140'><rand_op nr_op='1111' iban_platitor='RO27TREZ7005069XXX000455' den_trezorerie='Trezorerie operativa Municipiul Bucuresti' cui_beneficiar='39620' den_beneficiar='benef benef' iban_beneficiar='RO86TREZ022502250XXXXTVA' den_banca_trez='Trezorerie operativa Chisinau Cris ' suma_op='1458.25' nrevidpl='20603010000200917000031' explicatii='farararar explicatii' /><rand_op nr_op='2222' iban_platitor='RO27TREZ7005069XXX000455' den_trezorerie='Trezorerie operativa Municipiul Bucuresti' cui_beneficiar='39620' den_beneficiar='benef benef' iban_beneficiar='RO86TREZ022502250XXXXTVA' den_banca_trez='Trezorerie operativa Chisinau Cris ' suma_op='3756' nrevidpl='20603010000200917000031' explicatii='farararar explicatii' /><rand_op nr_op='3333' iban_platitor='RO27TREZ7005069XXX000455' den_trezorerie='Trezorerie operativa Municipiul Bucuresti' cui_beneficiar='140' den_beneficiar='benef benef' iban_beneficiar='RO86TREZ022502250XXXXTVA' den_banca_trez='Trezorerie operativa Chisinau Cris ' suma_op='3756' nrevidpl='20603010000200917000031' explicatii='farararar explicatii' /><rand_op nr_op='4444' iban_platitor='RO27TREZ7005069XXX000455' den_trezorerie='Trezorerie operativa Municipiul Bucuresti' cui_beneficiar='140' den_beneficiar='benef benef' iban_beneficiar='RO86TREZ022502250XXXXTVA' den_banca_trez='Trezorerie operativa Chisinau Cris ' suma_op='3756' nrevidpl='20603010000200917000031' explicatii='farararar explicatii' /></f1129>";
      //xfa.host.messageBox("this.Xml " + this.Xml);
      if(this.Xml == ""){
        return;
      }
      if(this.__ValidationMessages != ""){
        xfa.host.messageBox(this.__ValidationMessages, 'f' + this.Declaratie.Numar);
        this.__ValidationMessages = "";
        return;
      }
      //xfa.host.messageBox("2");
      this.__ClearFormData();
      //xfa.host.messageBox("3");
      this.LoadFormDataFromXml();
      //xfa.host.messageBox("4");
      //this.ValidateFormData(); 
      //csGlobals.Data().SumaControl.rawValue = "";
    };
    this.__ClearFormData = this.__ClearFormData?this.__ClearFormData:function(){
      // remove attached files
      this.__RemoveAttachedFiles();
      // remove table bugete rows
      /*
      var TheInstance = this.Data.TableOP._Row1;
      while (TheInstance.count > 1){
        TheInstance.removeInstance(1);
      }
      */
      // clear form data
      this.Form.resetForm();
    };
    this.__DoExecuteImport();
  };

    TheMethods.ExecuteExport = function(){
      //if(!this.ValidateFormData()){
      //  return;
      // }
    this.Form.exportDataObject({cName: '' + this.Declaratie.Numar + '.xml', nLaunch: 0});
  };



  TheMethods.LoadXmlFromFile = function(){
    this.__DoLoadXmlFromFile = this.__DoLoadXmlFromFile?this.__DoLoadXmlFromFile:function(){
      this.Xml = "";
      if(!this.Form.importDataObject('temp.xml')){
        return;
      }
      var TheFileStream = this.Form.getDataObjectContents('temp.xml');
      var TheRawXml = util.stringFromStream(TheFileStream, "utf-8");
      this.Xml = this.__CleanupXml(TheRawXml);
      //xfa.host.messageBox("this.Xml  " + this.Xml);
      var TheXmlTag = "<" + this.Declaratie.Numar + " ";
      if(this.Xml.indexOf(TheXmlTag) == -1){
        this.__ValidationMessages += "Fisierul XML importat nu este valid!\r\n";
        return;
      }
    };
    this.__CleanupXml = this.__CleanupXml?this.__CleanupXml:function(AnXml){
      if(!AnXml){
        return "";
      }
      var TheFileIndex = 0;
      var TheEol;  //windows file
      var TheEolIndex;
      var TheNewFile = "";
      if (AnXml.indexOf("\r\n") < 0) {
        TheEol = "\n"; //unix file
      } else {
        TheEol = "\r\n"; //windows file
      }
      while(TheFileIndex < AnXml.length){
        //eliminate BOM character for UTF-8 encoded files
        if ((TheFileIndex == 0) && ((AnXml.charCodeAt(0) == 0xFEFF) || (AnXml.charCodeAt(0) == 0xFFFE))){
          TheFileIndex++;
        }
        TheEolIndex = AnXml.indexOf(TheEol, TheFileIndex);
        if (TheEolIndex > 0){
          TheNewFile += AnXml.substring(TheFileIndex, TheEolIndex);
          TheFileIndex = TheEolIndex + TheEol.length;
        } else {
          TheNewFile += AnXml.substring(TheFileIndex, AnXml.length);
          TheFileIndex = AnXml.length;
        }
      }
      TheNewFile = TheNewFile.replace(/["]/g, "'");
      TheNewFile = TheNewFile.replace(/ =/g, "=");
      //TheNewFile = TheNewFile.replace(/= /g, "=");
      return TheNewFile;
    };
    this.__DoLoadXmlFromFile();
  };

  TheMethods.LoadFormDataFromXml = function(){
    this.__DoLoadFormDataFromXml = this.__DoLoadFormDataFromXml?this.__DoLoadFormDataFromXml:function(){
     this.__LoadHeader();
      //xfa.host.messageBox("this.Xml " +  this.Xml);
      //console.clear(); //console.println(this.Xml); 

	  // cite taguri docFd am, parcurg tot xml-ul
	  var CurrentdocFdIndex = this.Xml.indexOf('<docFd', 0);
      countdocFd = 0;
	  while(CurrentdocFdIndex != -1){
        //
        countdocFd += 1;
		CurrentdocFdIndex = this.Xml.indexOf('<docFd', CurrentdocFdIndex+1);
	  }
      //xfa.host.messageBox("countdocFd " +  countdocFd);
      // parcurg tagurile <docFd
	  if(countdocFd>0) {
	     this.__Load_docFd(countdocFd); 
	  }

	};


    this.__CurrentOPIndex = 0;
    this.__CurrentOPIndexMax = 0;
    this.__CurrentOPXml = '';

    this.__Load_docFd =  this.__Load_docFd?this.__Load_docFd:function(cnfFd){
        // parcurg tot xml-ul   
        var CurrentdocFdIndex = this.Xml.indexOf('<docFd', 0);
		//console.println("<docFd prima aparitie " + CurrentdocFdIndex + " aparitie " + "1" ); 
		var inceputdocFdIndex = CurrentdocFdIndex;
		var FdIndexSf = 0; 
		for(dfd = 1 ; dfd <= cnfFd; dfd++) {
		   // stabilesc inceputul si sfarsitul tagului <docFd
            //xfa.host.messageBox("dfd " + dfd );  
			if(dfd>1){       
     		   CurrentdocFdIndex = this.Xml.indexOf('<docFd', CurrentdocFdIndex+1);
               //console.println("<docFd prima aparitie " + CurrentdocFdIndex + " aparitie " + dfd ); 

