                                                 TheRowInf.SubformBeneficiar.SubformBen1.CifBeneficiar.rawValue+ "  " +
                                                 TheRowInf.SubformBeneficiar.SubformBen1.IbanBeneficiar.rawValue + "  " +
                                                 TheRowInf.SubformBeneficiar.SubformBen1.BancaBeneficiar.rawValue+ "  " +
                                                 TheRowInf.SubformBeneficiar.SubformBen1.InfPvPlata.rawValue+ "  " +
                                                 TheRowInf.SubformBeneficiar.SubformBen1.InfPvPlata1.rawValue) ;*/

         TheXml += "<docFd";
         TheXml += " nr_unic_inreg=\"" + TheRowInf.Subform1.NrUnicInreg.rawValue  + "\"";         
         TheXml += " beneficiar=\"" + TheRowInf.SubformBeneficiar.SubformBen.Beneficiar.rawValue  + "\"";         
         TheXml += " documente_justificative=\"" + TheRowInf.SubformBeneficiar.SubformBen.DocumenteJustificative.rawValue  + "\"";         
	     TheXml += " cif_beneficiar=\"" +  TheRowInf.SubformBeneficiar.SubformBen1.CifBeneficiar.rawValue + "\"";         
	     TheXml += " iban_beneficiar=\"" + TheRowInf.SubformBeneficiar.SubformBen1.IbanBeneficiar.rawValue + "\"";         
	     TheXml += " banca_beneficiar=\"" + TheRowInf.SubformBeneficiar.SubformBen1.BancaBeneficiar.rawValue + "\"";         
	     TheXml += " inf_pv_plata=\"" + TheRowInf.SubformBeneficiar.SubformBen1.InfPvPlata.rawValue + "\"";         
	     TheXml += " inf_pv_plata1=\"" + TheRowInf.SubformBeneficiar.SubformBen1.InfPvPlata1.rawValue + "\"";         
         TheXml += '>';
      	 //xfa.host.messageBox("i " + i  + " Table1._Row1.count " +  TheRowInf.Table1._Row1.count);
	     var cntTable1 = TheRowInf.Table1._Row1.count;

    	 for(j=1; j<cntTable1; j++ ) {
            //xfa.host.messageBox("i j" + i  + " " + j );
            var TheRow1 = TheRowInf.Table1.Row1.all.item(j);
            TheXml += "<rowTfd";
            TheXml += " cod_angajament=\"" + TheRow1.Cell1.rawValue  + "\"";         
            TheXml += " indicator_angajament=\"" + TheRow1.Cell2.rawValue  + "\"";         
            TheXml += " program=\"" + TheRow1.Cell3.rawValue  + "\"";         
            TheXml += " cod_SSI=\"" + TheRow1.Cell4.rawValue  + "\"";         
            TheXml += " receptii=\"" + TheRow1.Cell5.rawValue  + "\"";         
            TheXml += " plati_anterioare=\"" + TheRow1.Cell6.rawValue  + "\"";         
            TheXml += " suma_ordonantata_plata=\"" + TheRow1.Cell7.rawValue  + "\"";         
            TheXml += " receptii_neplatite=\"" + TheRow1.Cell8.rawValue  + "\"";         
            TheXml += '>';
            TheXml += '<\/' +   'rowTfd>';

		}
            TheXml += '<\/' +   'docFd>';

   }
      return TheXml;
  };


    this.__GenerateXmlForHeader = this.__GenerateXmlForHeader?this.__GenerateXmlForHeader:function(){
      var TheXml = ' DenInstPb=\"' + this.__Escape(this.Data.SubformAntet.DenInstPb.rawValue) + '\"'; 
      TheXml += ' Cif=\"' + this.__Escape(this.Data.SubformAntet.cif.rawValue.replace(/^\s+|\s+$/gm,'')) + '\"';
      TheXml += ' NrOrdonantPl=\"' + this.__Escape(this.Data.SubformAntet.NrOpl.rawValue.replace(/^\s+|\s+$/gm,''))+ '\"';
	  TheXml += ' DataOrdontPl=\"' + this.__FormatDate(this.Data.SubformAntet.DataOpl.rawValue)+ '\"';


       return TheXml;
    };
    this.__DoGenerateXml();
  };





 return TheMethods;
}

